function read_snapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    hit: select_rows(seam, `SELECT CASE WHEN json_valid("path") AND json_type("path") = 'object' AND json_type("path", '$.fn') = 'text' AND json_type("path", '$.args') = 'array' THEN json_extract("path", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("path", '$.args')), '') || ')' ELSE "path" END AS "path", "line", "col3" FROM "__txt_hit" t`, rel_columns.hit!, rel_column_types.hit!),
    hits: select_rows(seam, `SELECT CASE WHEN json_valid("path") AND json_type("path") = 'object' AND json_type("path", '$.fn') = 'text' AND json_type("path", '$.args') = 'array' THEN json_extract("path", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("path", '$.args')), '') || ')' ELSE "path" END AS "path", "col2" FROM "__txt_hits" t`, rel_columns.hits!, rel_column_types.hits!),
  });
}

type Snapshots = { readonly decoded: Snapshot; readonly stored: Snapshot };

function read_stored_snapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    hit: select_rows(seam, `SELECT "path", "line", "col3" FROM "hit"`, rel_columns.hit!, rel_column_types.hit!),
    hits: select_rows(seam, `SELECT "path", "col2" FROM "hits"`, rel_columns.hits!, rel_column_types.hits!),
  });
}

function read_snapshots(seam: ISqlSeam): Observable<Snapshots> {
  return forkJoin({ decoded: read_snapshot(seam), stored: read_stored_snapshot(seam) });
}

